import 'package:go7eight/src/core/app_export.dart';
import 'package:go7eight/src/core/enums/session_type_enum.dart';
import 'package:go7eight/src/core/reusableComponents/app_html_view.dart';
import '../../controllers/challenge_detail_controller.dart';

class ChallengeOverviewView extends GetView<GYMChallengeController> {
  final SessionType sessionType;

  const ChallengeOverviewView({super.key, required this.sessionType});
  @override
  Widget build(BuildContext context) {
    return ListView(
      shrinkWrap: true,
      padding: EdgeInsets.zero,
      physics: const NeverScrollableScrollPhysics(),
      children: [
        AppRatioSpaces.verticalSectionSpaceS(),
        const AppSectionTitle(
          title: "preference_qh_overview",
          titleColor: AppColor.primary,
          disableDefaultVPadding: true,
        ),
        _challengeDescription(context),
      ],
    );
  }

  _challengeDescription(BuildContext context) {
    return Container(
      margin: EdgeInsets.symmetric(
        horizontal: AppRatioSize.getRatioWidth() / 44,
      ),
      child: AppHtmlView.applyHtml(context,
          text: """
              <p><strong>How to perform one repetition :</strong></p>
<ul>
    <li style="font-size: 12px;">Stand upright with your legs slightly a part and your arms at your sides.</li>
    <li style="font-size: 12px;">With a little jump widen your legs and at the same time quickly bring the hands over your head, until their almost touch.</li>
</ul>
<p><strong>Muscles involved :</strong></p>
<p><span style="font-size: 12px;">Quadriceps Femoris, Gluteus Maximus, Biceps, Femoris, Gastrocnemius.</span></p>
<p><span data-buffer=""><img src="data:image/png;base64," width="181" height="174"></span></p>
<p><strong>Recommended repetitions :</strong></p>
<p><span style="font-size: 12px;">Beginner : 30s x 2 set<br>Intermediate : 45s &nbsp;x &nbsp;3 set<br>Advanced : 60s x 4 set</span></p>
<p></p>
<p><br></p>""",
          style: const TextStyle(),
          textAlign: TextAlign.left),
    );
  }
}
